<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Application\Usecase\Enable;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeAttributes;
use Civi\Lughauth\Features\Document\Theme\Application\Service\Visibility\ThemeVisibilityService;
use Civi\Lughauth\Features\Document\Theme\Domain\Gateway\ThemeWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeEnableUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly ThemeVisibilityService $visibility,
    private readonly ThemeWriteGateway $writer,
  ) {
  }

  public function allowEnable(?ThemeRef $ref = null): Allow
  {
    $this->logDebug("Check allow of Enable usecase for Theme");
    $span = $this->startSpan("Check allow of Enable usecase for Theme");
    try {
      $result = $this->dispatcher->dispatch(new ThemeEnableAllowDecision(Allow::allowed('enable', 'Allowed to Theme by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function enable(string $uid): ThemeEnableResult
  {
    $this->logDebug("Run Enable usecase for Theme");
    $span = $this->startSpan("Run Enable usecase for Theme");
    try {
      $ref = new ThemeRef($uid);
      $allow = $this->allowEnable($ref);
      if( !$allow->allowed ) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to Enable Theme');
      }
      if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
        throw new NotFoundException($uid);
      }
      $this->dispatcher->dispatch(new ThemeEnableCheck($original));
      $modified = $original->enable(  );
      $result= $this->writer->update($original, $modified);
      $output = $this->visibility->copyWithHidden( $this->visibility->prepareVisibleData( $result ) );
      return new ThemeEnableResult($output);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}